/*
 * mod-unbound: the Heroic Sigil vendors (ROADMAP.md "Heroic currency and vendor").
 *
 * Both sell for Heroic Sigils from a menu of pages; each page opens the vendor list of a never-spawned page creature
 * (their npc_vendor rows are generated by tools/heroic_loot.py). WorldSession::SendListInventory takes the page's
 * entry and remembers it as the current vendor, so buying (and the 2-hour refund) uses that page's list.
 *   - The Heroic Quartermaster (creature 190104, data/sql/db-world/unbound_heroic_quartermaster.sql): the 450 heroic
 *     dungeon items on five pages (190105-190109, QUARTERMASTER_PAGES), since a 3.3.5 vendor window holds at most
 *     150 items.
 *   - The Warden of Rare Wonders (creature 190200, data/sql/db-world/unbound_warden_of_rare_wonders.sql): cosmetics on
 *     four pages, Mounts, Pets, Tabards and Fun items (190201-190204, WARDEN_PAGES).
 */

#include "Creature.h"
#include "Player.h"
#include "ScriptMgr.h"
#include "ScriptedGossip.h"
#include "WorldSession.h"

#include <utility>
#include <vector>

namespace
{
    using Pages = std::vector<std::pair<uint32, char const*>>;  // vendor entry -> menu text

    // keep in sync with QUARTERMASTER_PAGES in tools/heroic_loot.py
    Pages const QUARTERMASTER_PAGES = {
        { 190105, "Rings, necks, cloaks, wrists and belts (10 Sigils)" },
        { 190106, "Head, shoulders and chest (15 Sigils)" },
        { 190107, "Hands, legs and feet (15 Sigils)" },
        { 190108, "Weapons, shields and off-hands (20-25 Sigils)" },
        { 190109, "Final boss treasures (30 Sigils)" },
    };

    // keep in sync with WARDEN_PAGES in tools/heroic_loot.py
    Pages const WARDEN_PAGES = {
        { 190201, "Mounts (85-250 Sigils)" },
        { 190202, "Pets (30-85 Sigils)" },
        { 190203, "Tabards (15 Sigils)" },
        { 190204, "Fun items (5-10 Sigils)" },
    };
}

// A vendor whose menu opens one of its page creatures' vendor lists; the greeting is npc_text `textId`.
class npc_unbound_sigil_vendor : public CreatureScript
{
public:
    npc_unbound_sigil_vendor(char const* name, uint32 textId, Pages const& pages)
        : CreatureScript(name), _textId(textId), _pages(pages) { }

    bool OnGossipHello(Player* player, Creature* creature) override
    {
        ClearGossipMenuFor(player);
        for (auto const& [entry, text] : _pages)
            AddGossipItemFor(player, GOSSIP_ICON_VENDOR, text, GOSSIP_SENDER_MAIN, entry);
        SendGossipMenuFor(player, _textId, creature->GetGUID());
        return true;
    }

    bool OnGossipSelect(Player* player, Creature* creature, uint32 /*sender*/, uint32 action) override
    {
        CloseGossipMenuFor(player);
        for (auto const& [entry, text] : _pages)
            if (entry == action)
                player->GetSession()->SendListInventory(creature->GetGUID(), entry);
        return true;
    }

private:
    uint32 _textId;
    Pages const& _pages;
};

void AddSC_unbound_heroic_quartermaster()
{
    new npc_unbound_sigil_vendor("npc_unbound_heroic_quartermaster", 190104, QUARTERMASTER_PAGES);
    new npc_unbound_sigil_vendor("npc_unbound_warden_of_rare_wonders", 190200, WARDEN_PAGES);
}
